import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.C7GIOALF.js";const c=JSON.parse('{"title":"Kingdom / BANG EDH","description":"","frontmatter":{},"headers":[],"relativePath":"formats/bang-like/variants/kingdom-bang-edh.md","filePath":"formats/bang-like/variants/kingdom-bang-edh.md","lastUpdated":null}'),i={name:"formats/bang-like/variants/kingdom-bang-edh.md"};function s(n,e,l,d,h,m){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="kingdom-bang-edh" tabindex="-1">Kingdom / BANG EDH <a class="header-anchor" href="#kingdom-bang-edh" aria-label="Permalink to &quot;Kingdom / BANG EDH&quot;">​</a></h1><p><a href="./../">BANG-like versions</a> · <strong>Rules: kesofcom&#39;s MTGSalvation version</strong></p><div class="warning custom-block"><p class="custom-block-title">Source ambiguity: Rogue victory</p><p>The source&#39;s Rogue condition says the other players are alive, while its strategy advice describes eliminating them and reaching a final duel. Both are recorded below. Choose an interpretation before play; this catalogue has not silently corrected the source into a new rule.</p></div><h2 id="players-and-materials" tabindex="-1">Players and materials <a class="header-anchor" href="#players-and-materials" aria-label="Permalink to &quot;Players and materials&quot;">​</a></h2><p>Use five or six Commander decks and one role card per player.</p><table tabindex="0"><thead><tr><th>Players</th><th style="text-align:right;">Emperor</th><th style="text-align:right;">Guard</th><th style="text-align:right;">Assassins</th><th style="text-align:right;">Rogue</th></tr></thead><tbody><tr><td>5</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td style="text-align:right;">2</td><td style="text-align:right;">1</td></tr><tr><td>6</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td style="text-align:right;">3</td><td style="text-align:right;">1</td></tr></tbody></table><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><ol><li>Prepare legal Commander decks and the listed role-card set.</li><li>Shuffle the roles and deal one to each player. Roles remain assigned for the entire game.</li><li>The Emperor reveals their card. Everyone else keeps theirs face down.</li><li>Each player starts at the normal Commander life total, except the Emperor receives <strong>+10 life</strong>, for <strong>50</strong>.</li><li>The Emperor also receives <strong>+1 opening hand size</strong> and <strong>+1 maximum hand size</strong>, giving eight cards for each instead of seven.</li><li>Take normal multiplayer mulligans with those hand-size adjustments.</li><li>The Emperor takes the first turn.</li></ol><h2 id="normal-play-and-role-visibility" tabindex="-1">Normal play and role visibility <a class="header-anchor" href="#normal-play-and-role-visibility" aria-label="Permalink to &quot;Normal play and role visibility&quot;">​</a></h2><p>Use ordinary individual Commander turns, combat, commander tax, and commander-damage rules. The roles create objectives rather than shared turns or shared resources.</p><p>Only the Emperor starts revealed. Reveal other roles when that player dies or the game ends. The source says players cannot concede; tables must decide before starting whether they intend to adopt that house restriction.</p><h2 id="table-talk" tabindex="-1">Table talk <a class="header-anchor" href="#table-talk" aria-label="Permalink to &quot;Table talk&quot;">​</a></h2><p>Do not discuss your role directly. You may discuss your actions, such as pointing out that you removed creatures attacking the Emperor.</p><p>Do not make out-of-game promises or stakes to prove a role. For example, offering to let somebody damage a physical card if you are lying is outside the source&#39;s permitted table talk.</p><h2 id="role-objectives" tabindex="-1">Role objectives <a class="header-anchor" href="#role-objectives" aria-label="Permalink to &quot;Role objectives&quot;">​</a></h2><ul><li><strong>Emperor:</strong> remain alive while all Assassins and the Rogue are dead. The Guard may be alive or dead.</li><li><strong>Guard:</strong> all Assassins and the Rogue must be dead, and the Emperor must remain alive. The Guard may die and still win.</li><li><strong>Assassins:</strong> the Emperor must be dead and the Rogue&#39;s victory condition must not have been satisfied. Eliminated Assassins can still share the Assassin victory.</li><li><strong>Rogue, literal posted condition:</strong> the Rogue is alive, every player other than the Emperor and Rogue is alive, and the Rogue kills the Emperor.</li><li><strong>Rogue, posted alternate condition:</strong> the Rogue kills every other player at once, remains alive, and the Emperor is last or tied for last to die.</li></ul><p>The literal Rogue wording conflicts with the same post&#39;s recommendation to remove the Assassins and reach a final duel. A table choosing “everyone else must be dead” is resolving that source ambiguity, not reading an unambiguous rule.</p><h2 id="elimination-rewards-and-penalties" tabindex="-1">Elimination rewards and penalties <a class="header-anchor" href="#elimination-rewards-and-penalties" aria-label="Permalink to &quot;Elimination rewards and penalties&quot;">​</a></h2><h3 id="an-assassin-dies" tabindex="-1">An Assassin dies <a class="header-anchor" href="#an-assassin-dies" aria-label="Permalink to &quot;An Assassin dies&quot;">​</a></h3><p>The player who killed that Assassin may draw up to <strong>three cards</strong>.</p><h3 id="the-emperor-kills-the-guard" tabindex="-1">The Emperor kills the Guard <a class="header-anchor" href="#the-emperor-kills-the-guard" aria-label="Permalink to &quot;The Emperor kills the Guard&quot;">​</a></h3><p>The Emperor exiles <strong>their nonland permanents, their graveyard, and their hand</strong>. This version says exile; do not replace it with another variant&#39;s sacrifice or discard penalty.</p><p>The source does not fully define kill credit for every simultaneous effect or concession. Agree how to handle such effects before relying on a reward or penalty.</p><h2 id="between-games-rogue-redeal" tabindex="-1">Between games: Rogue redeal <a class="header-anchor" href="#between-games-rogue-redeal" aria-label="Permalink to &quot;Between games: Rogue redeal&quot;">​</a></h2><p>A player who was the Rogue in the previous game may request that the next role deal be repeated until they are not the Rogue again. Resolve this before beginning the game.</p><h2 id="optional-two-kill-rogue-proposal" tabindex="-1">Optional two-kill Rogue proposal <a class="header-anchor" href="#optional-two-kill-rogue-proposal" aria-label="Permalink to &quot;Optional two-kill Rogue proposal&quot;">​</a></h2><p>The discussion proposes a Rogue victory for personally killing two players. It also identifies a conflict if the second victim is the Emperor. A group adopting this proposal must choose its additional restriction: either the second victim cannot be the Emperor, or a specific priority rule must prevent a simultaneous Rogue/Assassin victory. This is an unfinished alternate proposal, not part of the default role objectives.</p><p>Source: <a href="https://www.mtgsalvation.com/forums/the-game/commander-edh/616543-kingdom-aka-bang-edh-a-variant-format" target="_blank" rel="noreferrer">kesofcom&#39;s Kingdom / BANG EDH thread</a>. <a href="./../sources/kingdom-bang-edh-mtgsalvation.html">Archived notes</a>.</p>',28)])])}const p=a(i,[["render",s]]);export{c as __pageData,p as default};
